import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rounds = sc.nextInt();
        int[] alice = new int[rounds];
        int[] bob = new int[rounds];
        for (int i = 0; i < rounds; i++) {
            alice[i] = sc.nextInt();
        }
        for (int i = 0; i < rounds; i++) {
            bob[i] = sc.nextInt();
        }
        int[] bobRotated = new int[rounds];
        for (int i = 0; i < rounds; i++) {
            bobRotated[i] = bob[(i + 1) % rounds];
        }
        int minWin = 0;
        int maxWin = 0;
        for (int i = 0; i < rounds; i++) {
            maxWin += Math.min(alice[i], bobRotated[i]);
        }
        int maxBob = Arrays.stream(bobRotated).max().getAsInt();
        for (int i = 0; i < rounds; i++) {
            if (bobRotated[i] == maxBob && bobRotated[i] + alice[i] > minWin) {
                minWin = bobRotated[i] + alice[i];
            }
        }
        int maxAlice = Arrays.stream(alice).max().getAsInt();
        for (int i = 0; i < rounds; i++) {
            if (alice[i] == maxAlice && alice[i] + bobRotated[i] > minWin) {
                minWin = alice[i] + bobRotated[i];
            }
        }
        if (minWin > rounds) {
            minWin -= rounds;
        } else {
            minWin = 0;
        }
        System.out.println(minWin + " " + maxWin);
        sc.close();
    }
}
